quoted:
$ErrorActionPreference = 'Continue'
$log = 'C:\it''s\reinstall.log'
$version = '0.4.0'
$wanted = '0.4.0'
$program = 'C:\Program Files\Neutrino\agent\nagent.exe'
$started = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
function Get-Installed {
    if ($wanted -and (Test-Path -LiteralPath $program)) {
        return [string](& $program --version 2>$null | Select-Object -Last 1)
    }
    return ''
}
function Wait-Installer {
    $deadline = (Get-Date).AddSeconds(300)
    while ((Get-Date) -lt $deadline) {
        $held = $null
        try {
            if (-not [Threading.Mutex]::TryOpenExisting('Global\_MSIExecute', [ref]$held)) { return }
            $held.Dispose()
        } catch [UnauthorizedAccessException] {
        }
        Start-Sleep -Seconds 1
    }
}
function Invoke-Install {
    Wait-Installer
    if ($wanted -and (Get-Installed) -eq $wanted) {
        [IO.File]::WriteAllText($log, "already $wanted`n")
        return 0
    }
    $run = Start-Process -FilePath msiexec.exe -Wait -PassThru -NoNewWindow -ArgumentList '/i "C:\it''s\agent.msi" /qn /norestart /l*v "C:\it''s\reinstall.log"'
    return $run.ExitCode
}
$code = Invoke-Install
if ($code -eq 1618) { $code = Invoke-Install }
$note = ''
if ($wanted) {
    $installed = Get-Installed
    if ($installed -eq $wanted) {
        if (@(0, 3010) -notcontains $code) {
            $note = "already $wanted`n"
            $code = 0
        }
    } elseif (@(0, 3010) -contains $code) {
        if (-not $installed) { $installed = 'none' }
        $note = "found version $installed`n"
        $code = 1
    }
}
$finished = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
$output = ''
if (Test-Path -LiteralPath $log) {
    $output = [string](Get-Content -LiteralPath $log -Raw)
}
$output = ($output + $note).Replace("`r", '')
if ($output.Length -gt 4096) { $output = $output.Substring($output.Length - 4096) }
$result = [ordered]@{package = 'agent.msi'; kind = 'msi'; version = $version; started_at = $started; finished_at = $finished; exit_code = $code; output = $output}
[IO.File]::WriteAllText('C:\it''s\reinstall.json', ($result | ConvertTo-Json -Compress))

